---
import Layout from '../../layouts/Layout.astro';
import SoftwareCard from '../../components/SoftwareCard.astro';
import { categories, getSoftwareByCategory } from '../../data/software';

const { category } = Astro.params;

// Find the category name from the slug
const categoryName = categories.find(cat => 
	cat.toLowerCase().replace(' ', '-') === category
);

if (!categoryName) {
	return Astro.redirect('/categories');
}

const softwareList = getSoftwareByCategory(categoryName);
---

<Layout title={`${categoryName} Alternatives - Open Source Software`}>
	<div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-16">
		<!-- Breadcrumb -->
		<nav class="mb-8">
			<ol class="flex items-center space-x-2 text-sm">
				<li>
					<a href="/" class="text-secondary-500 hover:text-primary-600 transition-colors">Home</a>
				</li>
				<li class="text-secondary-400">/</li>
				<li>
					<a href="/categories" class="text-secondary-500 hover:text-primary-600 transition-colors">Categories</a>
				</li>
				<li class="text-secondary-400">/</li>
				<li class="text-secondary-900 font-medium">{categoryName}</li>
			</ol>
		</nav>

		<!-- Header -->
		<div class="text-center mb-12">
			<h1 class="text-4xl lg:text-5xl font-bold text-secondary-900 mb-6">
				{categoryName} Alternatives
			</h1>
			<p class="text-xl text-secondary-600 max-w-3xl mx-auto">
				Discover {softwareList.length} open source alternatives to popular {categoryName.toLowerCase()} software. 
				Find tools that respect your freedom and privacy.
			</p>
		</div>

		{softwareList.length === 0 ? (
			<div class="text-center py-20">
				<div class="w-20 h-20 bg-secondary-100 rounded-full flex items-center justify-center mx-auto mb-6">
					<svg class="w-10 h-10 text-secondary-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
						<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9.172 16.172a4 4 0 015.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/>
					</svg>
				</div>
				<h3 class="text-xl font-semibold text-secondary-900 mb-2">No alternatives found</h3>
				<p class="text-secondary-600 mb-6">
					We haven't added any {categoryName.toLowerCase()} alternatives yet. Check back soon!
				</p>
				<a href="/categories" class="inline-flex items-center px-4 py-2 text-sm font-medium text-primary-600 bg-primary-50 rounded-lg hover:bg-primary-100 transition-colors">
					Browse Other Categories
				</a>
			</div>
		) : (
			<>
				<!-- Software Grid -->
				<div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 mb-12">
					{softwareList.map((software) => (
						<SoftwareCard 
							name={software.name}
							description={software.description}
							category={software.category}
							license={software.license}
							website={software.website}
							github={software.github}
							tags={software.tags}
							featured={software.featured}
						/>
					))}
				</div>

				<!-- Related Categories -->
				<div class="bg-secondary-50 rounded-xl p-8 border border-secondary-200">
					<h3 class="text-2xl font-bold text-secondary-900 mb-6">Explore Related Categories</h3>
					<div class="grid grid-cols-2 md:grid-cols-4 gap-4">
						{categories
							.filter(cat => cat !== categoryName)
							.slice(0, 8)
							.map((relatedCategory) => {
								const slug = relatedCategory.toLowerCase().replace(' ', '-');
								const count = getSoftwareByCategory(relatedCategory).length;
								return (
									<a 
										href={`/categories/${slug}`}
										class="bg-white rounded-lg p-4 border border-secondary-200 hover:border-primary-300 hover:shadow-md transition-all duration-300"
									>
										<h4 class="font-medium text-secondary-900 mb-1">{relatedCategory}</h4>
										<p class="text-sm text-secondary-500">{count} alternatives</p>
									</a>
								);
							})}
					</div>
				</div>
			</>
		)}
	</div>
</Layout>
